# Generates ffmpeg-playground/src/hevc.rs: idct, dequant, add_residual,
# deblocking, SAO and intra prediction for HEVC (and VVC's SAO).
import re, sys
ex = {l.split("\t")[1].strip(): l.split("\t")[0] for l in open(sys.argv[1])}
def asm(name): return re.sub(r"^(h26x|vvc)_", "", ex[name].split("aarch64_")[1]) + ".S"
out = ['''//! libavcodec/aarch64 hevcdsp_idct_neon.S, hevcdsp_dequant_neon.S,
//! hevcdsp_deblock_neon.S, hevcpred_neon.S and h26x/sao_neon.S. Generated by
//! gen/hevc.py. High bit depths use u16 pixels with byte strides.
//!
//! Deblocking: an 8-sample edge segment, touching p3..q3 (luma) or p1..q1
//! (chroma; given the same 4-sample neighbourhood, which always exists around
//! a filtered edge); tc, no_p and no_q hold one entry per 4 samples. SAO edge
//! filtering reads its source from a CTB copy, bordered by one sample on
//! every side, with a stride of 2 * MAX_PB_SIZE + AV_INPUT_BUFFER_PADDING_SIZE
//! bytes: 192 for HEVC (edge_emu_buffer, which SAO deliberately runs on into
//! edge_emu_buffer2) and 320 for VVC (lc->sao.buffer); both hold whole rows
//! with room after them. The 8x8 variants serve blocks up to 8 wide, the 16x16
//! ones the rest (up to 64 for HEVC, 128 for VVC; sao_tab in */filter.c).
//! Widths and heights are CTB sizes clipped to the picture, multiples of 4
//! (chroma) or 8: picture sizes are multiples of MinCbSize. offset_val is
//! sao->offset_val[c_idx], a row of SAOParams' int16_t offset_val[3][5]; the
//! NEON code loads 8 entries, and from any row at least 8 remain before the
//! struct ends (type_idx and padding follow the array; 148 bytes in all).
//! SAO works on the frame in place: destinations (and the band filter's
//! source) are whole frame rows, which the NEON code reads and writes in
//! whole vectors past the CTB width at the picture's right edge, into the
//! row's alignment padding; a plane's pool adds 16 + STRIDE_ALIGN - 1 bytes
//! after its last row. Intra prediction reads the
//! decoder's left/top arrays (81 samples, used from index 1) and its filtered
//! copies (65, from 1).
use bums_macros as bums;
''']
def emit(name, args, pre, sig):
    if name not in ex:
        print("missing", name, file=sys.stderr); return
    out.append(f'''#[bums::check_mem_safe("{asm(name)}", {", ".join(args)},
    [{", ".join(pre)}])]
fn {name}({sig});
''')
for d in (8, 10, 12):
    ty, el = ("u8", 1) if d == 8 else ("u16", 2)
    row = "stride" if el == 1 else "stride / 2"
    even = ["stride % 2 == 0"] if el == 2 else []
    for n in (4, 8, 16, 32):
        emit(f"ff_hevc_add_residual_{n}x{n}_{d}_neon", ["dst.as_mut_ptr()", "coeffs.as_ptr()", "stride"],
             [f"dst.len() == {n - 1} * {row} + {n}", f"coeffs.len() == {n * n}", f"stride >= {n * el}", "stride <= 1073741824"] + even,
             f"dst: &mut [{ty}], coeffs: &[i16], stride: usize")
        emit(f"ff_hevc_idct_{n}x{n}_{d}_neon", ["coeffs.as_mut_ptr()", "col_limit"],
             [f"coeffs.len() == {n * n}", "col_limit >= 1", f"col_limit <= {n}"], "coeffs: &mut [i16], col_limit: usize")
        emit(f"ff_hevc_idct_{n}x{n}_dc_{d}_neon", ["coeffs.as_mut_ptr()"], [f"coeffs.len() == {n * n}"], "coeffs: &mut [i16]")
        emit(f"ff_hevc_dequant_{n}x{n}_{d}_neon", ["coeffs.as_mut_ptr()"], [f"coeffs.len() == {n * n}"], "coeffs: &mut [i16]")
    for edge in ("h", "v"):
        for comp in ("luma", "chroma"):
            # h: a horizontal edge (rows -4..3, 8 wide); v: a vertical one.
            ptr = f"pix.as_mut_ptr().add(4 * {row})" if edge == "h" else "pix.as_mut_ptr().add(4)"
            args = [ptr, "stride"] + (["beta"] if comp == "luma" else []) + ["tc.as_ptr()", "no_p.as_ptr()", "no_q.as_ptr()"]
            pre = [f"pix.len() == 7 * {row} + 8", f"stride >= {8 * el}", "stride <= 1073741824", "tc.len() == 2", "no_p.len() == 2", "no_q.len() == 2"] + even
            if comp == "luma": pre.append("beta <= 255")
            sig = f"pix: &mut [{ty}], stride: usize" + (", beta: usize" if comp == "luma" else "") + ", tc: &[i32], no_p: &[u8], no_q: &[u8]"
            emit(f"ff_hevc_{edge}_loop_filter_{comp}_{d}_neon", args, pre, sig)
    # The 16x16 variants serve every width that rounds up past 8; listed, so
    # each check runs with the width pinned and the column loop is concrete.
    def widths(wmax):
        if wmax == 8:
            return "width % 4 == 0, width >= 4, width <= 8"
        return " || ".join(f"width == {w}" for w in range(12, wmax + 1, 4))
    for codec in ("hevc", "vvc"):
        # VVC CTBs reach 128 (sao_tab[16] in vvc/filter.c), HEVC's 64.
        big = 128 if codec == "vvc" else 64
        for size, wmax in (("8x8", 8), ("16x16", big)):
            # The copy's stride, in bytes at every bit depth:
            # 2 * MAX_PB_SIZE + AV_INPUT_BUFFER_PADDING_SIZE.
            s = (320 if codec == "vvc" else 192) // el
            drow = "stride_dst" if el == 1 else "(stride_dst / 2)"
            emit(f"ff_{codec}_sao_edge_filter_{size}_{d}_neon",
                 ["dst.as_mut_ptr()", f"src.as_ptr().add({s + 1})", "stride_dst", "offset_val.as_ptr()", "eo", "width", "height"],
                 [f"dst.len() == height * {drow}", f"src.len() == (height + 2) * {s} + {16 // el}", "offset_val.len() == 8", "eo <= 3",
                  widths(wmax), "height % 4 == 0", "height >= 4", f"height <= {big}",
                  f"stride_dst >= {wmax * el}", "stride_dst <= 1073741824"] + (["stride_dst % 2 == 0"] if el == 2 else []),
                 f"dst: &mut [{ty}], src: &[{ty}], stride_dst: usize, offset_val: &[i16], eo: usize, width: usize, height: usize")
for size, wmax in (("8x8", 8), ("16x16", 128)):
    emit(f"ff_h26x_sao_band_filter_{size}_8_neon",
         ["dst.as_mut_ptr()", "src.as_ptr()", "stride_dst", "stride_src", "offset_val.as_ptr()", "left_class", "width", "height"],
         ["dst.len() == height * stride_dst", "src.len() == height * stride_src + 16", "offset_val.len() == 8",
          "left_class <= 31", widths(wmax), "height % 4 == 0", "height >= 4", "height <= 128",
          f"stride_dst >= {wmax}", f"stride_src >= {wmax}", "stride_dst <= 1073741824", "stride_src <= 1073741824"],
         "dst: &mut [u8], src: &[u8], stride_dst: usize, stride_src: usize, offset_val: &[i16], left_class: usize, width: usize, height: usize")
emit("ff_hevc_transform_luma_4x4_neon_8", ["coeffs.as_mut_ptr()"], ["coeffs.len() == 16"], "coeffs: &mut [i16]")
arrays = ["src.len() == {m} * stride + {n}", "stride >= {n}", "stride <= 1073741824", "top.len() == 81", "left.len() == 81"]
for n in (4, 8, 16, 32):
    pre = [a.format(m=n - 1, n=n) for a in arrays]
    emit(f"ff_hevc_pred_dc_{n}x{n}_8_neon", ["src.as_mut_ptr()", "top.as_ptr().add(1)", "left.as_ptr().add(1)", "stride", "c_idx"],
         pre + ["c_idx <= 2"], "src: &mut [u8], top: &[u8], left: &[u8], stride: usize, c_idx: usize")
    emit(f"ff_hevc_pred_planar_{n}x{n}_8_neon", ["src.as_mut_ptr()", "top.as_ptr().add(1)", "left.as_ptr().add(1)", "stride"],
         pre, "src: &mut [u8], top: &[u8], left: &[u8], stride: usize")
for n in (8, 16, 32):
    emit(f"ff_hevc_ref_filter_3tap_{n}x{n}_8_neon",
         ["filtered_left.as_mut_ptr().add(1)", "filtered_top.as_mut_ptr().add(1)", "left.as_ptr().add(1)", "top.as_ptr().add(1)", "size"],
         ["filtered_left.len() == 65", "filtered_top.len() == 65", "left.len() == 81", "top.len() == 81", f"size == {n}"],
         "filtered_left: &mut [u8], filtered_top: &mut [u8], left: &[u8], top: &[u8], size: usize")
emit("ff_hevc_ref_filter_strong_8_neon", ["filtered_top.as_mut_ptr().add(1)", "left.as_mut_ptr().add(1)", "top.as_ptr().add(1)"],
     ["filtered_top.len() == 65", "left.len() == 81", "top.len() == 81"], "filtered_top: &mut [u8], left: &mut [u8], top: &[u8]")
for mode in (10, 26):
    emit(f"ff_hevc_pred_angular_mode_{mode}_8_neon",
         ["src.as_mut_ptr()", "top.as_ptr().add(1)", "left.as_ptr().add(1)", "stride", "c_idx", "log2_size"],
         ["src.len() == 31 * stride + 32", "stride >= 32", "stride <= 1073741824",
          "top.len() == 81", "left.len() == 81", "c_idx <= 2", "log2_size >= 2", "log2_size <= 5"],
         "src: &mut [u8], top: &[u8], left: &[u8], stride: usize, c_idx: usize, log2_size: usize")
print("\n".join(out))
